CREATE FUNCTION dropalltables(schemaname character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  ts VARCHAR(100);
  tn VARCHAR(100);
BEGIN
    for ts,tn
    in select table_schema,table_name from information_schema.tables
       where table_schema= schemaname and 
             (table_type='table' or table_type='BASE TABLE')
    loop
      EXECUTE 'DROP TABLE ' || ts || '."' || tn || '" CASCADE';
    end loop;
END;
$$;


