--
-- TOC entry 881 (class 1259 OID 91272)
-- Name: rc2; Type: VIEW; Schema: mondial_rdf2sql_standard; Owner: -
--

CREATE VIEW rc2 AS
 SELECT md.tablename,
    md.lookupattr,
    md.class AS rangetable
   FROM md
  WHERE ((md.inv)::text = 'true'::text)
UNION
 SELECT DISTINCT md1.tablename,
    md1.lookupattr,
    md2.class AS rangetable
   FROM md md1,
    nmj,
    md md2
